import {readFile,writeFile} from 'node:fs/promises';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';

const root=dirname(fileURLToPath(import.meta.url));
const sourcePath=join(root,'static/app.source.js');
const vendorPath=join(root,'static/vendor/html2canvas.esm.min.js');
const outputPath=join(root,'static/app.js');
const source=await readFile(sourcePath,'utf8');
let vendor=await readFile(vendorPath,'utf8');
const exportStatement='export{Vg as default};';
if(!vendor.includes(exportStatement))throw new Error('html2canvas 发布文件格式已变化，请更新打包脚本');
vendor=vendor.replace(exportStatement,'return Vg;').replace(/\n\/\/# sourceMappingURL=.*$/,'');
const firstBreak=source.indexOf('\n');
if(firstBreak<0 || !source.startsWith('import '))throw new Error('app.source.js 缺少引擎导入语句');
const engineImport=source.slice(0,firstBreak),application=source.slice(firstBreak+1);
const banner='/* Generated by build_app_bundle.mjs. Edit app.source.js, then rebuild. */';
await writeFile(outputPath,`${banner}\n${engineImport}\nconst html2canvas=(()=>{\n${vendor}\n})();\n${application}`);
console.log('已生成 static/app.js（内置 html2canvas）');
